# Linker version script: export ONLY the public FFI API (everything Dart calls),
# hide internal helpers. Smaller .dynsym + direct intra-library calls (no PLT).
# Used by the release build: -Wl,--version-script=ffz.map
{
  global:
    ffz_config_default; ffz_config_match_paths;
    ffz_str_from_utf8; ffz_str_buf_free;
    ffz_indices_clear; ffz_indices_free; ffz_indices_sort_dedup;
    ffz_matcher_new; ffz_matcher_free; ffz_matcher_config; ffz_match;
    ffz_pattern_parse; ffz_pattern_new; ffz_pattern_free; ffz_pattern_match;
    ffz_corpus_new; ffz_corpus_free; ffz_corpus_set_transliterator;
    ffz_corpus_add; ffz_corpus_len; ffz_corpus_clear; ffz_corpus_filter;
    ffz_results_free;
    ffz_parallel_off; ffz_parallel_auto; ffz_parallel_with;
  local:
    *;
};
